public class Main {
    public static void main(String[] args) {
        String studentName = "Priya Sharma";
        int studentId = 1042;
        double gpa = 9.25;

        // Header
        System.out.println("=============================");
        System.out.println("      STUDENT PROFILE        ");
        System.out.println("=============================");

        // Same line label + value using print and println
        System.out.print("ID:        ");
        System.out.println(studentId);

        System.out.print("Name:      ");
        System.out.println(studentName);

        System.out.print("GPA:       ");
        System.out.println(gpa);

        // Table layout with tab escape sequences
        System.out.println("\nCourse\t\tCredits\tGrade");
        System.out.println("Data Structures\t4\tA+");
        System.out.println("Database Systems\t3\tA");
        System.out.println("Java Programming\t4\tO");
    }
}

